fn amount_of(text: Str) -> Result[Int, Str] {
  if text.is_empty() or not text.is_numeric() {
    return Err("bad op")
  }
  let n = text.to_int().unwrap_or(0)
  if n <= 0 {
    return Err("bad op")
  }
  return Ok(n)
}

fn balance_of(accts: Map[Str, Int], name: Str) -> Result[Int, Str] {
  if not accts.has(name) {
    return Err("unknown " + name)
  }
  return Ok(accts.get(name).unwrap_or(0))
}

fn do_open(accts: Map[Str, Int], name: Str) -> Result[Map[Str, Int], Str] {
  if accts.has(name) {
    return Err("exists " + name)
  }
  return Ok(accts.set(name, 0))
}

fn do_dep(accts: Map[Str, Int], name: Str, amt: Int) -> Result[Map[Str, Int], Str] {
  let bal = balance_of(accts, name)?
  return Ok(accts.set(name, bal + amt))
}

fn do_wd(accts: Map[Str, Int], name: Str, amt: Int) -> Result[Map[Str, Int], Str] {
  let bal = balance_of(accts, name)?
  if bal < amt {
    return Err("insufficient " + name)
  }
  return Ok(accts.set(name, bal - amt))
}

fn do_move(accts: Map[Str, Int], src: Str, dst: Str, amt: Int) -> Result[Map[Str, Int], Str] {
  let from_bal = balance_of(accts, src)?
  let to_bal = balance_of(accts, dst)?
  if from_bal < amt {
    return Err("insufficient " + src)
  }
  if src == dst {
    return Ok(accts)
  }
  let after = accts.set(src, from_bal - amt)
  return Ok(after.set(dst, to_bal + amt))
}

fn apply_op(accts: Map[Str, Int], op: Str) -> Result[Map[Str, Int], Str] {
  let parts = op.split(" ")
  let cmd = parts.get_or(0, "")
  let n = parts.len()
  if cmd == "open" {
    if n != 2 {
      return Err("bad op")
    }
    return do_open(accts, parts.get_or(1, ""))
  }
  if cmd == "dep" or cmd == "wd" {
    if n != 3 {
      return Err("bad op")
    }
    let amt = amount_of(parts.get_or(2, ""))?
    if cmd == "dep" {
      return do_dep(accts, parts.get_or(1, ""), amt)
    }
    return do_wd(accts, parts.get_or(1, ""), amt)
  }
  if cmd == "move" {
    if n != 4 {
      return Err("bad op")
    }
    let amt = amount_of(parts.get_or(3, ""))?
    return do_move(accts: accts, src: parts.get_or(1, ""), dst: parts.get_or(2, ""), amt: amt)
  }
  return Err("bad op")
}

fn apply_all(ops: List[Str], accts: Map[Str, Int]) -> Result[Map[Str, Int], Str] {
  if ops.is_empty() {
    return Ok(accts)
  }
  let next = apply_op(accts, ops.first().unwrap_or(""))?
  return apply_all(ops: ops.drop(1), accts: next)
}

pub fn ledger(ops: List[Str]) -> Result[Map[Str, Int], Str] {
  let empty: Map[Str, Int] = Map {}
  return apply_all(ops: ops, accts: empty)
}
